  static void Main(string[] args){
    Console.InputEncoding=new UTF8Encoding(false);Console.OutputEncoding=new UTF8Encoding(false);
    try{
      if(args.Length!=1&&args.Length!=5)throw new Exception("Argumentos inválidos.");store=Full(args[0]);if(store==""||!store.EndsWith("\\uninstaller",StringComparison.OrdinalIgnoreCase)||!Under(store,Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData))&&!Under(store,Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData)))throw new Exception("Armazenamento fora do AppData.");Directory.CreateDirectory(store);SafeFs.NoLinks(store);
      LoadSnapshots();
      if(args.Length==5){if(!Admin||args[1]!="--pipe"||args[3]!="--pid"||!System.Text.RegularExpressions.Regex.IsMatch(args[2],"^ntc-uninstaller-[a-f0-9]{64}$"))throw new Exception("Canal inválido.");int parent=int.Parse(args[4]);string protectedRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"NTC Utilities Uninstaller Backups");ProtectStore(protectedRoot);store=Path.Combine(protectedRoot,WindowsIdentity.GetCurrent().User.Value);ProtectStore(store);LoadSnapshots();var security=new PipeSecurity();security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.ReadWrite,AccessControlType.Allow));using(var pipe=new NamedPipeServerStream(args[2],PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.None,65536,65536,security)){pipe.WaitForConnection();uint pid;if(!GetNamedPipeClientProcessId(pipe.SafePipeHandle,out pid)||pid!=parent)throw new Exception("Cliente não autorizado.");using(var reader=new StreamReader(pipe,new UTF8Encoding(false)))using(var writer=new StreamWriter(pipe,new UTF8Encoding(false))){writer.AutoFlush=true;Serve(reader,writer);}}}
