    }catch(Exception e){Console.Error.WriteLine(e.Message);Environment.ExitCode=1;}
  }
  static void ProtectStore(string dir){SafeFs.NoLinks(dir);var admins=new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null);var system=new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null);if(Directory.Exists(dir)){var acl=Directory.GetAccessControl(dir);var owner=(SecurityIdentifier)acl.GetOwner(typeof(SecurityIdentifier));if(!owner.Equals(admins)&&!owner.Equals(system))throw new Exception("Pasta de backups elevados existente não tem proprietário confiável. Operação bloqueada.");}else Directory.CreateDirectory(dir);var security=new DirectorySecurity();security.SetOwner(admins);security.SetAccessRuleProtection(true,false);foreach(var sid in new[]{admins,system})security.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(dir,security);}
  static void LoadSnapshots(){snapshots.Clear();string dir=Path.Combine(store,"snapshots");if(!Directory.Exists(dir))return;SafeFs.NoLinks(dir);foreach(var f in Directory.GetFiles(dir,"*.json"))try{var s=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(f));snapshots[S(s,"id")]=s;}catch{}}
  static void Serve(TextReader reader,TextWriter writer){string line;while((line=reader.ReadLine())!=null){object seq=null;try{if(line.Length>1024*1024)throw new Exception("Pedido grande demais.");var r=json.Deserialize<Dictionary<string,object>>(line);seq=r["seq"];var payload=(Dictionary<string,object>)r["payload"];var result=Dispatch(S(r,"action"),payload);writer.WriteLine(json.Serialize(D("seq",seq,"result",result)));}catch(Exception e){writer.WriteLine(json.Serialize(D("seq",seq,"error",e.Message)));}}}
}

